def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    # Compress coordinates: every boundary where a cell's status can change.
    pts = {1, n + 1}
    for op in ops:
        pts.add(op[1])
        pts.add(op[2] + 1)
    pts = sorted(pts)
    idx = {p: i for i, p in enumerate(pts)}
    m = len(pts) - 1  # number of elementary intervals

    # Each node holds a pending operation (reset_flag, value) for its subtree.
    # Blank is 0, which is below every colour, so paint is a range chmax.
    tf = [False] * (4 * m)
    tv = [0] * (4 * m)

    def apply(node, f, v):
        if f:
            tf[node] = True
            tv[node] = v
        elif v > tv[node]:
            tv[node] = v

    def push(node):
        apply(2 * node, tf[node], tv[node])
        apply(2 * node + 1, tf[node], tv[node])
        tf[node] = False
        tv[node] = 0

    def update(node, lo, hi, a, b, f, v):
        if b < lo or hi < a:
            return
        if a <= lo and hi <= b:
            apply(node, f, v)
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, a, b, f, v)
        update(2 * node + 1, mid + 1, hi, a, b, f, v)

    vals = [0] * m

    def collect(node, lo, hi):
        if lo == hi:
            vals[lo] = tv[node]
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid + 1, hi)

    for op in ops:
        a = idx[op[1]]
        b = idx[op[2] + 1] - 1
        if op[0] == 1:
            update(1, 0, m - 1, a, b, False, op[3])
        else:
            update(1, 0, m - 1, a, b, True, 0)

    collect(1, 0, m - 1)

    counts = {}
    for i in range(m):
        c = vals[i]
        if c > 0:
            counts[c] = counts.get(c, 0) + (pts[i + 1] - pts[i])

    return [[c, counts[c]] for c in sorted(counts)]
